INSERT INTO tradeskill_recipe(`id`,`name`,`tradeskill`,`skillneeded`,`trivial`,`nofail`,`replace_container`,`notes`,`must_learn`,`learned_by_item_id`,`quest`,`enabled`,`min_expansion`,`max_expansion`,`content_flags`,`content_flags_disabled`)SELECT e.`id`,e.`name`,e.`tradeskill`,e.`skillneeded`,e.`trivial`,e.`nofail`,e.`replace_container`,e.`notes`,e.`must_learn`,e.`learned_by_item_id`,e.`quest`,e.`enabled`,e.`min_expansion`,e.`max_expansion`,e.`content_flags`,e.`content_flags_disabled` FROM `_tbs_recipes` e WHERE @tbs_recipes_ok=1 AND NOT EXISTS(SELECT 1 FROM tradeskill_recipe a WHERE a.id=e.id);
INSERT INTO tradeskill_recipe_entries(`recipe_id`,`item_id`,`successcount`,`failcount`,`componentcount`,`salvagecount`,`iscontainer`)SELECT e.`recipe_id`,e.`item_id`,e.`successcount`,e.`failcount`,e.`componentcount`,e.`salvagecount`,e.`iscontainer` FROM `_tbs_recipe_entries` e WHERE @tbs_recipes_ok=1 AND NOT EXISTS(SELECT 1 FROM tradeskill_recipe_entries a WHERE a.`recipe_id`<=>e.`recipe_id` AND a.`item_id`<=>e.`item_id` AND a.`successcount`<=>e.`successcount` AND a.`failcount`<=>e.`failcount` AND a.`componentcount`<=>e.`componentcount` AND a.`salvagecount`<=>e.`salvagecount` AND a.`iscontainer`<=>e.`iscontainer`);
COMMIT;
